meta={q['id']:q for q in curated};out=[]
def add(qid,text,options=None,extra=None):
    blocks=[{'type':'text','text':text}]
    if extra:blocks+=extra
    if options:blocks.append({'type':'options','items':options})
    out.append({'id':qid,'blocks':blocks,'verified':True,'sourceSha256':meta[qid]['sourceSha256']})
def batch(prefix,items):
    for n,text in items.items():add(prefix+str(n),text)
def svg(body,w=240,h=150):return f'<svg xmlns="http://www.w3.org/2000/svg" width="{w}" height="{h}" viewBox="0 0 {w} {h}"><g stroke="#111" fill="none" stroke-width="1.2">{body}</g></svg>'
def label(x,y,t):return f'<text x="{x}" y="{y}" stroke="none" fill="#111" font-family="Noto Sans TC,serif" font-size="13">{html.escape(str(t))}</text>'
def diagram(qid,body,w=240,h=150):add(qid, r'如圖，求 $x=\underline{\qquad}$。' if 'fill-16' not in qid else r'如圖，求 $y=\underline{\qquad}$。',extra=[{'type':'svg','svg':svg(body,w,h)}])

