def chart(xlabels,series,ymax,ystep,xlabel,ylabel,w=460,h=230,labels=False):
    left,top,right,bottom=56,25,w-20,h-52;body=''
    for v in range(0,ymax+1,ystep):
        y=bottom-(bottom-top)*v/ymax;body+=f'<path d="M{left} {y} H{right}" stroke="#b5b5b5"/>'+label(left-26,y+4,v)
    for i,xlab in enumerate(xlabels):
        x=left+(right-left)*i/(len(xlabels)-1);body+=label(x-10,bottom+18,xlab)
    body+=f'<path d="M{left} {top} V{bottom} H{right}"/>'+label(left,15,ylabel)+label(right-100,h-5,xlabel)
    for values,dashed,name in series:
        pts=[(left+(right-left)*i/(len(xlabels)-1),bottom-(bottom-top)*v/ymax) for i,v in enumerate(values)];body+=f'<polyline points="'+ ' '.join(f'{x},{y}' for x,y in pts)+'"'+(' stroke-dasharray="5 3"' if dashed else '')+'/>'
        for i,(x,y) in enumerate(pts):
            body+=f'<circle cx="{x}" cy="{y}" r="2" fill="#111"/>'
            if labels and i:body+=label(x+3,y-4,values[i])
        if name:
            ly=11 if not dashed else 29
            body+=f'<path d="M{right-145} {ly} H{right-110}"'+(' stroke-dasharray="5 3"' if dashed else '')+'/>'+label(right-100,ly+4,name)
    return svg(body,w,h)
